def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_C = opp.count('C')
    opp_D = n - opp_C
    my_D = my.count('D')

    # Defect on the very last round.
    if n == 99:
        return 'D'

    # If opponent has never cooperated by round 6, they are likely a pure defector.
    if n >= 6 and opp_C == 0:
        return 'D'

    # If opponent has never defected, probe/exploit.
    if opp_D == 0:
        if n >= 6:
            return 'D'
        else:
            return 'C'

    # Base: cooperate if opponent cooperated last round.
    last_opp = opp[-1]
    if last_opp == 'C':
        return 'C'

    # Opponent defected last round.
    # If their defection matches our action from two rounds ago, it's a TFT-style retaliation.
    if n >= 2 and opp[-1] == my[-2]:
        return 'C'

    return 'D'
